// FilesServiceServer is the server API for FilesService service.
// All implementations must embed UnimplementedFilesServiceServer
// for forward compatibility.
//
// FilesService provides file management with streaming upload/download.
type FilesServiceServer interface {
	// Initialize a new upload session, returns upload_id and chunk parameters.
	InitiateUpload(context.Context, *InitiateUploadRequest) (*InitiateUploadResponse, error)
	// Upload a single chunk (browser-compatible unary RPC).
	// Call this for each chunk, then call CompleteUpload when done.
	UploadChunk(context.Context, *UploadChunkRequest) (*UploadChunkResponse, error)
	// Complete an upload after all chunks have been sent.
	CompleteUpload(context.Context, *CompleteUploadRequest) (*CompleteUploadResponse, error)
	// Stream file chunks to backend (client streaming RPC - server-to-server only).
	// NOTE: This does not work in browsers due to Fetch API limitations.
	UploadChunks(grpc.ClientStreamingServer[UploadChunksRequest, UploadChunksResponse]) error
	// Get status of an in-progress upload (for resuming after disconnect).
	GetUploadStatus(context.Context, *GetUploadStatusRequest) (*GetUploadStatusResponse, error)
	// Abort an in-progress upload.
	AbortUpload(context.Context, *AbortUploadRequest) (*AbortUploadResponse, error)
	// Stream file content from backend to client (server streaming RPC).
	DownloadFile(*DownloadFileRequest, grpc.ServerStreamingServer[DownloadFileResponse]) error
	// Get a file by ID.
	GetFile(context.Context, *GetFileRequest) (*GetFileResponse, error)
	// Update file metadata (rename, tags, description).
	UpdateFile(context.Context, *UpdateFileRequest) (*UpdateFileResponse, error)
	// Delete a file (soft delete by default).
	DeleteFile(context.Context, *DeleteFileRequest) (*DeleteFileResponse, error)
	// Restore a soft-deleted file.
	RestoreFile(context.Context, *RestoreFileRequest) (*RestoreFileResponse, error)
	// List files with pagination and filters.
	ListFiles(context.Context, *ListFilesRequest) (*ListFilesResponse, error)
	// Create a new folder.
	CreateFolder(context.Context, *CreateFolderRequest) (*CreateFolderResponse, error)
	// Update a folder.
	UpdateFolder(context.Context, *UpdateFolderRequest) (*UpdateFolderResponse, error)
	// Delete a folder.
	DeleteFolder(context.Context, *DeleteFolderRequest) (*DeleteFolderResponse, error)
	// Get the full file/folder tree.
	GetFilesTree(context.Context, *GetFilesTreeRequest) (*GetFilesTreeResponse, error)
	// Create a folder tree in a single transaction (for recursive folder upload).
	CreateFolderTree(context.Context, *CreateFolderTreeRequest) (*CreateFolderTreeResponse, error)
	// Lazily create or fetch the per-user "Recordings" folder. Idempotent under
	// concurrent invocations across backend instances. Used by the screen
	// recording feature to resolve the upload destination on first record.
	EnsureRecordingsFolder(context.Context, *EnsureRecordingsFolderRequest) (*EnsureRecordingsFolderResponse, error)
	// Move files/folders to a different parent.
	MoveItems(context.Context, *MoveItemsRequest) (*MoveItemsResponse, error)
	// Copy files (not folders) to a different location.
	CopyItems(context.Context, *CopyItemsRequest) (*CopyItemsResponse, error)
	// Bulk delete multiple files/folders.
	BulkDelete(context.Context, *BulkDeleteRequest) (*BulkDeleteResponse, error)
	// Empty trash (permanently delete all soft-deleted files).
	EmptyTrash(context.Context, *EmptyTrashRequest) (*EmptyTrashResponse, error)
	// List deleted files and folders (trash).
	ListTrash(context.Context, *ListTrashRequest) (*ListTrashResponse, error)
	// Restore a soft-deleted folder (and its contents) back to its parent.
	RestoreFolder(context.Context, *RestoreFolderRequest) (*RestoreFolderResponse, error)
	// List version history for a file.
	ListFileVersions(context.Context, *ListFileVersionsRequest) (*ListFileVersionsResponse, error)
	// Restore a previous version of a file.
	RestoreFileVersion(context.Context, *RestoreFileVersionRequest) (*RestoreFileVersionResponse, error)
	// Get the organization storage quota configuration.
	GetOrgStorageQuota(context.Context, *GetOrgStorageQuotaRequest) (*GetOrgStorageQuotaResponse, error)
	// Set or update the organization storage quota configuration.
	SetOrgStorageQuota(context.Context, *SetOrgStorageQuotaRequest) (*SetOrgStorageQuotaResponse, error)
	// Get a user's effective storage quota and current usage.
	GetUserStorageQuota(context.Context, *GetUserStorageQuotaRequest) (*GetUserStorageQuotaResponse, error)
	// Set or update a per-user quota override.
	SetUserStorageQuotaOverride(context.Context, *SetUserStorageQuotaOverrideRequest) (*SetUserStorageQuotaOverrideResponse, error)
	// Remove a per-user quota override (reverts to org default).
	RemoveUserStorageQuotaOverride(context.Context, *RemoveUserStorageQuotaOverrideRequest) (*RemoveUserStorageQuotaOverrideResponse, error)
	// List all per-user quota overrides in an organization.
	ListUserStorageQuotaOverrides(context.Context, *ListUserStorageQuotaOverridesRequest) (*ListUserStorageQuotaOverridesResponse, error)
	// Get storage usage for a specific user (own usage for regular users).
	GetStorageUsage(context.Context, *GetStorageUsageRequest) (*GetStorageUsageResponse, error)
	// List storage usage for all users in an organization (admin only).
	ListOrgStorageUsage(context.Context, *ListOrgStorageUsageRequest) (*ListOrgStorageUsageResponse, error)
	// Recalculate storage usage from actual files (admin, drift correction).
	RecalculateStorageUsage(context.Context, *RecalculateStorageUsageRequest) (*RecalculateStorageUsageResponse, error)
	// Pre-check whether an upload of a given size is allowed under quota.
	CheckStorageQuota(context.Context, *CheckStorageQuotaRequest) (*CheckStorageQuotaResponse, error)
	// Create a new saved filter.
	CreateSavedFilter(context.Context, *CreateSavedFilterRequest) (*CreateSavedFilterResponse, error)
	// Get a saved filter by ID.
	GetSavedFilter(context.Context, *GetSavedFilterRequest) (*GetSavedFilterResponse, error)
	// Update a saved filter.
	UpdateSavedFilter(context.Context, *UpdateSavedFilterRequest) (*UpdateSavedFilterResponse, error)
	// Delete a saved filter.
	DeleteSavedFilter(context.Context, *DeleteSavedFilterRequest) (*DeleteSavedFilterResponse, error)
	// List saved filters for the current user.
	ListSavedFilters(context.Context, *ListSavedFiltersRequest) (*ListSavedFiltersResponse, error)
	// Attach a file to content. If the file is not already in the Attachments
	// folder it is copied there. Upload new attachments via InitiateUpload with
	// the folder id from GetAttachmentsFolder, then call AttachFile to link.
	AttachFile(context.Context, *AttachFileRequest) (*AttachFileResponse, error)
	// Detach a file from content (deletes the attachment and the file copy).
	DetachFile(context.Context, *DetachFileRequest) (*DetachFileResponse, error)
	// List all attachments for a piece of content.
	ListAttachments(context.Context, *ListAttachmentsRequest) (*ListAttachmentsResponse, error)
	// Batch-list attachments for many content rows of the same type. Used by
	// chat to hydrate attachments for a page of messages in one round-trip
	// (replaces an N+1 ListAttachments fan-out).
	BatchListAttachments(context.Context, *BatchListAttachmentsRequest) (*BatchListAttachmentsResponse, error)
	// Get the user's Attachments folder id. Use it with InitiateUpload to
	// upload new attachments.
	GetAttachmentsFolder(context.Context, *GetAttachmentsFolderRequest) (*GetAttachmentsFolderResponse, error)
	mustEmbedUnimplementedFilesServiceServer()
}

